(function () {
  window.medinfoExams = [

    { name: 'Digital Images & Medical Imaging', questions: [
      {id:"mi-img-001",topic:"Digital Images",subtopic:"Resolution",difficulty:"Easy",question:"How much is the resolution of a digital image which has 1000 pixels in rows and 1000 pixels in columns?",options:{A:"1 Megabyte",B:"1 Megabit",C:"1 Megapixel",D:"1 Byte"},correct:"C",explanation:"Resolution = rows × columns = 1000 × 1000 = 1,000,000 pixels = 1 Megapixel. Resolution is measured in pixels, not bytes or bits."},
      {id:"mi-img-002",topic:"Digital Images",subtopic:"File size",difficulty:"Medium",question:"The size of a digital image file (in bits) is given by:",options:{A:"Number of pixels in a row multiplied by number of pixels in a column",B:"Number of pixels in a row multiplied by color depth",C:"Number of pixels in a row multiplied by number of pixels in a column multiplied by color depth",D:"Number of pixels in a column multiplied by color depth only"},correct:"C",explanation:"Image file size (bits) = width × height × color depth. For example, a 1000×1000 image with 24-bit color = 24,000,000 bits. Resolution alone (rows × columns) gives the pixel count, not the file size."},
      {id:"mi-img-003",topic:"Digital Images",subtopic:"Smallest element",difficulty:"Easy",question:"The smallest element in a 2D digital image is called:",options:{A:"Boxel",B:"Excel",C:"Matrix",D:"Pixel"},correct:"D",explanation:"A pixel (picture element) is the smallest unit of a 2D digital image. In 3D imaging, the equivalent is a voxel."},
      {id:"mi-img-004",topic:"Digital Images",subtopic:"Color depth",difficulty:"Medium",question:"What is color depth?",options:{A:"The number of pixels per row in the image",B:"The contrast between lightest and darkest areas of the image",C:"The number of bits used to indicate the color of a single pixel",D:"The width and height dimensions of the image in pixels"},correct:"C",explanation:"Color depth (bit depth) defines how many bits are used to represent the color of each pixel. For example, 8-bit = 256 colors, 24-bit = ~16.7 million colors."},
      {id:"mi-img-005",topic:"Digital Images",subtopic:"Histogram Y-axis",difficulty:"Medium",question:"Which quantity is on the vertical (Y) axis of an image histogram?",options:{A:"Frequency of pixels / number of pixels",B:"Brightness",C:"Resolution",D:"Contrast"},correct:"A",explanation:"In an image histogram, the Y-axis shows the frequency (count) of pixels at each brightness level. The X-axis represents the brightness values."},
      {id:"mi-img-006",topic:"Digital Images",subtopic:"Histogram X-axis",difficulty:"Medium",question:"Which quantity is on the horizontal (X) axis of an image histogram?",options:{A:"Frequency of pixels",B:"Resolution",C:"Contrast",D:"Brightness"},correct:"D",explanation:"The X-axis of an image histogram represents the brightness (intensity) values, ranging from 0 (black) to 255 (white) in an 8-bit image."},
      {id:"mi-img-007",topic:"Digital Images",subtopic:"Quantization",difficulty:"Medium",question:"What is true about image quantization in the image digitization process?",options:{A:"It divides an image into pixels and determines the resolution",B:"It means selecting a specific region of interest (ROI) in a digital image",C:"It means recoding an image in bytes for writing into a data file",D:"It assigns a numerical value to every pixel representing its brightness"},correct:"D",explanation:"Quantization assigns a discrete numerical value (brightness level) to each pixel during digitization. Sampling divides the image into pixels (determines resolution); quantization determines the grey/color levels."},
      {id:"mi-img-008",topic:"Digital Images",subtopic:"Greyscale",difficulty:"Medium",question:"In a greyscale image using 1 byte per pixel, how many different shades of grey can be represented?",options:{A:"8",B:"16",C:"128",D:"256"},correct:"D",explanation:"1 byte = 8 bits. 2^8 = 256 possible values (0–255), representing 256 shades of grey from black (0) to white (255)."},
      {id:"mi-img-009",topic:"Digital Images",subtopic:"Colour channels",difficulty:"Medium",question:"A standard colour image uses three channels: Red, Green, and Blue. If each channel uses 1 byte, what is the total colour depth per pixel?",options:{A:"8 bits",B:"16 bits",C:"24 bits",D:"32 bits"},correct:"C",explanation:"3 channels × 8 bits per channel = 24 bits per pixel. This gives 2^24 ≈ 16.7 million possible colours."},
      {id:"mi-img-010",topic:"Medical Imaging",subtopic:"DICOM",difficulty:"Medium",question:"What is DICOM?",options:{A:"A hospital management software for patient administration",B:"A standard for medical images controlling their handling, storing, printing, and transmitting",C:"A judicious use of current best evidence in making health care decisions",D:"A standard for peripheral I/O devices used in medicine such as biosignal sensors"},correct:"B",explanation:"DICOM (Digital Imaging and Communications in Medicine) is the international standard for handling, storing, printing, and transmitting medical imaging information."},
      {id:"mi-img-011",topic:"Medical Imaging",subtopic:"PACS",difficulty:"Medium",question:"What does PACS stand for in the context of medical imaging?",options:{A:"Patient Archive and Clinical System",B:"Picture Archiving and Communication System",C:"Portable Acquisition and Conversion Software",D:"Primary Access and Computing Server"},correct:"B",explanation:"PACS (Picture Archiving and Communication System) is a medical imaging technology that provides storage, retrieval, and distribution of images, integrated with HIS/RIS."},
      {id:"mi-img-012",topic:"Digital Images",subtopic:"Voxel",difficulty:"Easy",question:"What is a voxel?",options:{A:"The smallest element of a 2D image",B:"A pixel with colour information",C:"The smallest element of a 3D image (volume element)",D:"The unit of image resolution in radiology"},correct:"C",explanation:"A voxel (volume element) is the 3D equivalent of a pixel, representing a value in a three-dimensional space, used in CT, MRI, and PET imaging."},
      {id:"mi-img-013",topic:"Digital Images",subtopic:"Sampling",difficulty:"Medium",question:"In image digitization, what does the sampling process determine?",options:{A:"The brightness value assigned to each pixel",B:"The file format used to save the image",C:"The number of pixels in each dimension (the resolution)",D:"The colour depth of the image"},correct:"C",explanation:"Sampling divides the continuous image into a grid of pixels, determining spatial resolution (pixels per row and column). Quantization separately determines the brightness levels per pixel."},
      {id:"mi-img-014",topic:"Digital Images",subtopic:"Image size calculation",difficulty:"Hard",question:"A digital image is 512×512 pixels with a colour depth of 8 bits. What is the file size in kilobytes (without compression)?",options:{A:"256 KB",B:"512 KB",C:"2048 KB",D:"262144 KB"},correct:"A",explanation:"512 × 512 = 262,144 pixels × 8 bits = 2,097,152 bits ÷ 8 = 262,144 bytes ÷ 1024 = 256 KB."},
      {id:"mi-img-015",topic:"Digital Images",subtopic:"Contrast",difficulty:"Easy",question:"In digital imaging, contrast refers to:",options:{A:"The total number of colours in the image",B:"The number of pixels per unit area",C:"The difference in brightness between the lightest and darkest pixels",D:"The physical size of the image sensor"},correct:"C",explanation:"Contrast is the difference in brightness between the lightest and darkest areas of an image. High contrast images have a wide range of brightness values."},
    ]},

    { name: 'Computer Hardware & Software', questions: [
      {id:"mi-hw-001",topic:"Hardware",subtopic:"CPU",difficulty:"Easy",question:"What is a CPU (central processing unit)?",options:{A:"Software to control all computer sources",B:"Device to store information",C:"Algorithm written in computer language",D:"Executive hardware unit able to perform program instructions"},correct:"D",explanation:"The CPU is the executive hardware unit that interprets and executes program instructions. It is composed of an arithmetic logic unit (ALU), control unit (CU), and registers."},
      {id:"mi-hw-002",topic:"Data",subtopic:"Bit",difficulty:"Easy",question:"What is true about a bit?",options:{A:"10 different values can be saved in one bit",B:"Only 2 different values can be saved in one bit (e.g. yes/no)",C:"100 different values can be saved in one bit",D:"2^10 different values can be saved in one bit"},correct:"B",explanation:"A bit (binary digit) is the basic unit of information and can hold exactly 2 values: 0 or 1 (yes/no, true/false, on/off)."},
      {id:"mi-hw-003",topic:"Data",subtopic:"Byte",difficulty:"Easy",question:"What is true about a Byte?",options:{A:"1 Byte is a connection of 4 bits",B:"1 Byte is a connection of 16 bits",C:"1 Byte is a connection of 8 bits (1 Byte = 8 bits)",D:"1 Byte equals 1 bit of information"},correct:"C",explanation:"1 Byte = 8 bits. A byte can represent 2^8 = 256 different values (0–255). Bytes are the standard unit for measuring data storage."},
      {id:"mi-hw-004",topic:"Data",subtopic:"Data units",difficulty:"Medium",question:"Which sequence correctly orders data units from smallest to largest?",options:{A:"Bit → Byte → Kilobyte → Megabyte → Gigabyte",B:"Byte → Bit → Kilobyte → Gigabyte → Megabyte",C:"Kilobyte → Byte → Bit → Megabyte → Gigabyte",D:"Bit → Kilobyte → Byte → Megabyte → Gigabyte"},correct:"A",explanation:"The correct order is: bit < byte (8 bits) < KB (1024 bytes) < MB (1024 KB) < GB (1024 MB) < TB (1024 GB)."},
      {id:"mi-hw-005",topic:"Hardware",subtopic:"Hardware examples",difficulty:"Easy",question:"Which of the following is an example of computer hardware?",options:{A:"Microsoft Word",B:"Operating system",C:"Graphics card",D:"Web browser"},correct:"C",explanation:"Hardware refers to physical components of a computer. A graphics card is hardware. Microsoft Word, operating systems, and web browsers are software (programs stored in the computer)."},
      {id:"mi-hw-006",topic:"Hardware",subtopic:"Software definition",difficulty:"Easy",question:"What is software?",options:{A:"Physical components of a computer such as RAM and CPU",B:"Programs stored in computer memory and composed of instructions in bits",C:"The network cables connecting computers",D:"The physical input devices such as keyboard and mouse"},correct:"B",explanation:"Software consists of programs — sets of instructions stored in the computer's memory as bits — that tell the hardware what to do. Examples include operating systems, word processors, and applications."},
      {id:"mi-hw-007",topic:"Data",subtopic:"Primary key",difficulty:"Medium",question:"What is a primary key in a database table?",options:{A:"A record containing unique values for all attributes",B:"An attribute containing only unique values for each record in the table",C:"An attribute containing values that may frequently repeat in the table",D:"A database object containing only unique table names"},correct:"B",explanation:"A primary key is a column (attribute) whose values uniquely identify each record (row) in a database table. No two rows can have the same primary key value, and it cannot be NULL."},
      {id:"mi-hw-008",topic:"Hardware",subtopic:"CPU components",difficulty:"Medium",question:"The CPU is composed of which main components?",options:{A:"RAM, ROM, and hard drive",B:"Arithmetic logic unit (ALU), control unit (CU), and registers",C:"Monitor, keyboard, and graphics card",D:"Operating system, browser, and antivirus"},correct:"B",explanation:"The CPU consists of: (1) Arithmetic Logic Unit — performs calculations and logical operations; (2) Control Unit — fetches and interprets instructions; (3) Registers — small fast storage holding data during processing."},
      {id:"mi-hw-009",topic:"Data",subtopic:"IP address",difficulty:"Medium",question:"What is an IP address?",options:{A:"A physical address burned into the network card",B:"A numerical label (32 bits, divided by dots) given to each device on a network",C:"The name of a host on the internet",D:"A reference to a resource on the internet"},correct:"B",explanation:"An IP address (IPv4) is a 32-bit numerical label divided into 4 octets separated by dots (e.g., 192.168.1.10) assigned to each device for identification on a network."},
      {id:"mi-hw-010",topic:"Hardware",subtopic:"Memory types",difficulty:"Medium",question:"Which statement correctly describes RAM?",options:{A:"Read-only memory that stores the BIOS and cannot be changed",B:"Volatile random access memory used as working memory during computer operation",C:"Permanent storage on a magnetic hard drive",D:"Flash storage used in USB drives and SSDs"},correct:"B",explanation:"RAM (Random Access Memory) is volatile working memory — it temporarily stores data and programs in use, and its contents are lost when the computer is turned off."},
      {id:"mi-hw-011",topic:"Data",subtopic:"Information system",difficulty:"Easy",question:"What is an information system?",options:{A:"A computer network connecting hospitals internationally",B:"A combination of people, hardware, software, and data resources to process information",C:"A database used exclusively for medical records",D:"An operating system used in hospitals"},correct:"B",explanation:"An information system is a combination of people, hardware, software, data, and processes that collect, process, store, and distribute information."},
      {id:"mi-hw-012",topic:"Hardware",subtopic:"HIS",difficulty:"Easy",question:"What is HIS?",options:{A:"High intensity storage system",B:"Hospital identification series",C:"Hospital information system",D:"Hospital IP sorting"},correct:"C",explanation:"HIS (Hospital Information System) is an information system designed to manage all aspects of a hospital's operations — administrative, clinical, and financial."},
    ]},

    { name: 'Computer Networks', questions: [
      {id:"mi-net-001",topic:"Networks",subtopic:"Definition",difficulty:"Easy",question:"What is a computer network?",options:{A:"Computing power of several computers summed up to work as one",B:"A system where several users share one computer at the same time",C:"An interconnected system of autonomous computers that can exchange information",D:"One control unit with peripheries absolutely dependent on it"},correct:"C",explanation:"A computer network is an interconnected system of autonomous computers that can exchange information. Unlike a computer terminal, each computer retains its autonomy."},
      {id:"mi-net-002",topic:"Networks",subtopic:"PAN",difficulty:"Easy",question:"What is a PAN (Personal Area Network)?",options:{A:"A network interconnecting users in a metropolitan area",B:"A network interconnecting devices of an individual (computer, smartphone, tablet)",C:"A telecommunications network extending far distances",D:"A computer network in a room or building"},correct:"B",explanation:"A PAN (Personal Area Network) interconnects devices belonging to one individual — e.g., a smartphone, laptop, and tablet connected via Bluetooth or USB. Range: typically within ~10 metres."},
      {id:"mi-net-003",topic:"Networks",subtopic:"LAN",difficulty:"Easy",question:"Which type of network is a home WiFi network with one access point?",options:{A:"MAN",B:"WAN",C:"LAN",D:"PAN"},correct:"C",explanation:"A LAN (Local Area Network) covers a small geographic area such as a home, room, or building. Home WiFi with one access point is a typical LAN example."},
      {id:"mi-net-004",topic:"Networks",subtopic:"Network types",difficulty:"Medium",question:"Which network type interconnects users across a metropolitan area (city)?",options:{A:"PAN",B:"LAN",C:"MAN",D:"WAN"},correct:"C",explanation:"A MAN (Metropolitan Area Network) covers a city or metropolitan area. WAN covers large geographic distances (countries/continents); LAN covers a building; PAN covers a single person's devices."},
      {id:"mi-net-005",topic:"Networks",subtopic:"WAN",difficulty:"Easy",question:"What is a WAN (Wide Area Network)?",options:{A:"A network limited to one building",B:"A personal device network",C:"A telecommunications network extending far distances across countries or continents",D:"A network interconnecting users within a city"},correct:"C",explanation:"A WAN (Wide Area Network) is a telecommunications network that extends over large geographic distances, connecting LANs and MANs. The internet is the largest WAN."},
      {id:"mi-net-006",topic:"Networks",subtopic:"Peer-to-peer",difficulty:"Medium",question:"How do we call the architecture of a network where computers are equally privileged, equipotent participants in the application?",options:{A:"Terminator architecture",B:"Client-Server architecture",C:"IPVP architecture",D:"Peer-to-peer architecture"},correct:"D",explanation:"In peer-to-peer (P2P) architecture, every computer can act as both client and server — all are equally privileged. In client-server architecture, roles never change: the server always serves, the client always requests."},
      {id:"mi-net-007",topic:"Networks",subtopic:"Client-server",difficulty:"Medium",question:"In a client-server network architecture, which statement is correct?",options:{A:"Every computer can be either a client or server at any time",B:"The client can only receive information from the server it is connected to; roles never change",C:"All computers share equal responsibility for data storage",D:"The server is usually a weaker computer than the clients"},correct:"B",explanation:"In client-server architecture, the server always provides resources/services and the client always requests them — roles never swap. Clients can only receive from their server."},
      {id:"mi-net-008",topic:"Networks",subtopic:"Firewall",difficulty:"Easy",question:"What does a firewall do?",options:{A:"Protects against network disconnection (dropouts)",B:"Scans for viruses on your system",C:"Blocks unwanted network communication",D:"Scans for spyware on your system"},correct:"C",explanation:"A firewall monitors and filters incoming and outgoing network traffic based on security rules — it blocks unwanted or unauthorized network communication."},
      {id:"mi-net-009",topic:"Networks",subtopic:"Domain address",difficulty:"Easy",question:"What is a domain address?",options:{A:"A numerical label given to each device on a network",B:"A reference to a resource on the internet",C:"Text with a reference to another text",D:"The name of a host on the internet"},correct:"D",explanation:"A domain address (domain name) is the human-readable name of a host on the internet (e.g., www.cuni.cz). It is translated into an IP address by DNS."},
      {id:"mi-net-010",topic:"Networks",subtopic:"URL",difficulty:"Easy",question:"What is a URL?",options:{A:"A numerical label for a network device",B:"A reference to a resource on the internet",C:"Text with a hyperlink to another document",D:"The physical address of a network card"},correct:"B",explanation:"A URL (Uniform Resource Locator) is a reference to a resource on the internet — it specifies its location and the protocol to retrieve it (e.g., https://www.example.com/page)."},
      {id:"mi-net-012",topic:"Networks",subtopic:"MAC address",difficulty:"Medium",question:"What is a MAC address?",options:{A:"A dynamic IP address assigned by the router",B:"A web address for accessing hospital networks",C:"A numerical label divided by dots assigned to devices",D:"A physical address permanently assigned to a network interface card"},correct:"D",explanation:"A MAC (Media Access Control) address is a unique physical address burned into a network interface card (NIC). Unlike IP addresses, MAC addresses are fixed hardware identifiers."},
    ]},

    { name: 'MS Office: Excel & Word', questions: [
      {id:"mi-off-001",topic:"MS Excel",subtopic:"Multiplication formula",difficulty:"Easy",question:"Choose the correct example of multiplication of two cells A1 and A2 in MS Excel:",options:{A:"=A1$A2",B:"=A1%A2",C:"=A1@A2",D:"=A1*A2"},correct:"D",explanation:"In MS Excel, the multiplication operator is *. Correct formulas must start with = and use * for multiplication: =A1*A2. Other operators: + (add), - (subtract), / (divide), ^ (power)."},
      {id:"mi-off-002",topic:"MS Excel",subtopic:"Absolute address",difficulty:"Medium",question:"Choose the correct example of an absolute address in MS Excel:",options:{A:"#A#1",B:"$A$1",C:"%A%1",D:"A1"},correct:"B",explanation:"Absolute references use $ signs before column and row: $A$1. When you copy a formula, absolute references do not change. Relative references (e.g., A1) change when copied."},
      {id:"mi-off-003",topic:"MS Excel",subtopic:"Division formula",difficulty:"Easy",question:"Choose the correct expression to divide cells A1 and A2 in MS Excel:",options:{A:"$A1/$A2",B:"=A1%A2",C:"=A1/A2",D:"A1/A2"},correct:"C",explanation:"Division in Excel uses / operator. The formula must start with =. =A1/A2 divides the value in A1 by the value in A2."},
      {id:"mi-off-004",topic:"MS Excel",subtopic:"Relative vs absolute",difficulty:"Medium",question:"Absolute and relative referencing are features likely to be found in which of the following software packages?",options:{A:"Text processor (e.g. MS Word)",B:"Database (e.g. MS Access)",C:"Email program (e.g. MS Outlook)",D:"Spreadsheets (e.g. MS Excel)"},correct:"D",explanation:"Absolute ($A$1) and relative (A1) referencing are features of spreadsheet software like MS Excel. They control how cell references change when formulas are copied."},
      {id:"mi-off-005",topic:"MS Word",subtopic:"Table of contents",difficulty:"Medium",question:"What do we have to do when we want to generate an automatic table of contents in MS Word?",options:{A:"Set correct font size for each heading",B:"Set correct font for each heading",C:"Set correct style for each heading",D:"Set correct color for each heading"},correct:"C",explanation:"For an automatic table of contents, each heading must be formatted with the built-in Heading styles (Heading 1, Heading 2, etc.) — not just font size or color. Word then generates the TOC from those styles automatically."},
      {id:"mi-off-006",topic:"MS Word",subtopic:"Automatic heading",difficulty:"Medium",question:"An automatic heading is formed when you change the style of text and not the text font, font size, or colour. This allows MS Word to:",options:{A:"Change the font automatically when printing",B:"Save the document in a different format",C:"Generate an automatic table of contents from heading styles",D:"Apply spell check to heading text only"},correct:"C",explanation:"When you apply heading styles rather than manual formatting, Word recognizes the document structure and can automatically generate a table of contents, navigation pane entries, and document maps."},
      {id:"mi-off-007",topic:"MS Excel",subtopic:"RANK function",difficulty:"Hard",question:"Which Excel formula calculates the rank of a value using the average rank for ties?",options:{A:"=RANK(value; ref; order)",B:"=RANK.AVG(value; ref; order)",C:"=AVERAGE.RANK(value; ref)",D:"=AVG.RANK(ref; value; order)"},correct:"B",explanation:"RANK.AVG returns the average rank when multiple values are tied. RANK.EQ returns the highest rank for ties. Syntax: =RANK.AVG(number; ref; [order]) where order 0 = descending, 1 = ascending."},
      {id:"mi-off-008",topic:"MS Excel",subtopic:"Conditional formatting",difficulty:"Medium",question:"In MS Excel, colour scales for conditional formatting are found in which menu?",options:{A:"Insert → Charts",B:"Home → Conditional Formatting",C:"Data → Data Tools",D:"View → Freeze Panes"},correct:"B",explanation:"Conditional Formatting is in the Home tab in MS Excel. Colour scales automatically apply a gradient of colours based on cell values, making it easy to visualise data distributions."},
      {id:"mi-off-009",topic:"MS Excel",subtopic:"Calculate mode",difficulty:"Medium",question:"Calculate the mode (modus) of the following data: 7, 1, 9, 7, 4, 4, 3, 7, 5",options:{A:"4",B:"5",C:"7",D:"9"},correct:"C",explanation:"The mode is the value that appears most frequently. In this dataset: 7 appears 3 times, 4 appears 2 times, all others appear once. Mode = 7. In Excel: =MODE(A1:A9) or =MODE.SNGL(A1:A9)."},
      {id:"mi-off-010",topic:"MS Excel",subtopic:"Calculate median",difficulty:"Medium",question:"Calculate the median of the following data: 8, 5, 2, 3, 1, 8, 2, 5, 1",options:{A:"2",B:"3",C:"5",D:"8"},correct:"B",explanation:"Sorted: 1, 1, 2, 2, 3, 5, 5, 8, 8 — 9 values, so the median is the 5th value = 3. In Excel: =MEDIAN(A1:A9)."},
      {id:"mi-off-012",topic:"MS Excel",subtopic:"AVERAGE function",difficulty:"Easy",question:"In MS Excel, which function calculates the arithmetic mean of a range of values?",options:{A:"=MEAN(A1:A10)",B:"=AVG(A1:A10)",C:"=AVERAGE(A1:A10)",D:"=SUM(A1:A10)/COUNT(A1:A10) only"},correct:"C",explanation:"=AVERAGE(range) calculates the arithmetic mean of a range in Excel. The function =SUM/COUNT also works but AVERAGE is the dedicated function."},
    ]},

    { name: 'Databases & Searching', questions: [
      {id:"mi-db-001",topic:"Databases",subtopic:"Primary key",difficulty:"Medium",question:"What is a primary key in a relational database?",options:{A:"A record containing unique values for every attribute in the table",B:"An attribute containing only unique values for each record, used to identify each row",C:"An attribute whose values frequently repeat throughout the table",D:"A database object containing only unique table names"},correct:"B",explanation:"A primary key is a column (or set of columns) whose values uniquely identify each row in a table. Each value must be unique and cannot be NULL. It is the fundamental concept of relational database integrity."},
      {id:"mi-db-002",topic:"Databases",subtopic:"Boolean AND",difficulty:"Medium",question:"What does AND mean when you create a query in a database or search engine?",options:{A:"It reduces the number of results (all terms must be present)",B:"It broadens the results by including either term",C:"It increases the number of results",D:"It does not take the first keyword into account"},correct:"A",explanation:"AND is a Boolean operator that requires all specified terms to be present in results — this narrows/reduces results. OR broadens results (either term). NOT excludes terms."},
      {id:"mi-db-003",topic:"Databases",subtopic:"Boolean OR",difficulty:"Medium",question:"What does OR mean when you create a query in a database or search engine?",options:{A:"It requires all terms to be present, narrowing results",B:"It excludes the specified term from results",C:"It broadens results — at least one of the terms must be present",D:"It does not take the last keyword into account"},correct:"C",explanation:"OR is a Boolean operator that returns results containing any of the specified terms — this broadens/increases results. Example: 'hypertension OR high blood pressure' returns both."},
      {id:"mi-db-004",topic:"Databases",subtopic:"Boolean NOT",difficulty:"Medium",question:"What does NOT mean when you create a query in a database or search engine?",options:{A:"It requires all terms to be present",B:"It broadens results by including either term",C:"It takes every term into account equally",D:"It excludes the specified term, narrowing results"},correct:"D",explanation:"NOT (Boolean operator) excludes a term from search results, narrowing the search. Example: 'cancer NOT lung' returns cancer results excluding lung cancer."},
      {id:"mi-db-005",topic:"Databases",subtopic:"Scientific databases",difficulty:"Medium",question:"Which of the following options is an online subscription-based scientific citation indexing database covering full text articles, reviews, editorials, chronologies, abstracts, and proceedings?",options:{A:"Web of Science",B:"Wikipedia",C:"Open Access",D:"Nature"},correct:"A",explanation:"Web of Science is a subscription-based citation indexing database. Wikipedia is a free encyclopaedia. Nature is a scientific journal. Open Access refers to free-to-read publications, not a database itself."},
      {id:"mi-db-006",topic:"Databases",subtopic:"Free literature",difficulty:"Easy",question:"Which resource provides free, peer-reviewed medical literature?",options:{A:"Web of Science",B:"PubMed / MEDLINE",C:"Elsevier ScienceDirect",D:"Cochrane Library subscription"},correct:"B",explanation:"PubMed/MEDLINE is a free database from the US National Library of Medicine providing access to biomedical literature. Web of Science and ScienceDirect are subscription-based."},
      {id:"mi-db-007",topic:"Databases",subtopic:"Hypertext",difficulty:"Easy",question:"What is hypertext?",options:{A:"A numerical label given to each device on a network",B:"Text with a reference (link) to another text or document",C:"A method of image compression",D:"An encrypted data transmission protocol"},correct:"B",explanation:"Hypertext is text that contains links (hyperlinks) to other texts or documents. It is the foundation of the World Wide Web — HTML (HyperText Markup Language) is the basis for web pages."},
      {id:"mi-db-008",topic:"Databases",subtopic:"Table structure",difficulty:"Easy",question:"In a database table, data is organized as:",options:{A:"Colour-coded cells arranged by priority",B:"Rows (records) and columns (attributes/fields)",C:"Nested folders with file attachments",D:"Sequential numbered lists only"},correct:"B",explanation:"A database table organizes data into rows (records/tuples — individual entries) and columns (attributes/fields — categories of information). This structure allows systematic querying."},
      {id:"mi-db-009",topic:"Databases",subtopic:"Search boolean combination",difficulty:"Hard",question:"A researcher searches for 'heart AND failure NOT pediatric'. Which result best describes the search outcome?",options:{A:"All articles about heart, failure, or pediatric topics",B:"Articles about pediatric heart failure",C:"Articles containing both 'heart' and 'failure' but not 'pediatric'",D:"Articles containing 'heart' or 'failure' but excluding nothing"},correct:"C",explanation:"AND requires both 'heart' and 'failure' to be present. NOT excludes 'pediatric'. Result: adult/general heart failure literature, excluding pediatric articles."},
      {id:"mi-db-010",topic:"Databases",subtopic:"HIS functionality",difficulty:"Medium",question:"What is the primary function of a Hospital Information System (HIS)?",options:{A:"To connect all hospital computers to the internet",B:"To provide free peer-reviewed literature to hospital staff",C:"To manage all aspects of a hospital's administrative and clinical operations",D:"To archive medical images in DICOM format"},correct:"C",explanation:"A HIS is designed to manage all aspects of a hospital's operations including patient administration, clinical records, scheduling, billing, and reporting — integrating all hospital departments."},
    ]},

    { name: 'Medical Statistics', questions: [
      {id:"mi-stat-001",topic:"Statistics",subtopic:"Prevalence",difficulty:"Easy",question:"The proportion of individuals in a defined population that has the outcome (disease) under study at a defined instant (a point) in time is:",options:{A:"Mortality",B:"Prevalence",C:"Lethality",D:"Incidence"},correct:"B",explanation:"Prevalence = number of existing cases / total population at a specific point in time. It is a proportion (not a rate). It includes both new and old cases at that moment."},
      {id:"mi-stat-002",topic:"Statistics",subtopic:"Incidence",difficulty:"Easy",question:"Occurrence of new cases of disease over a specified time period, typically calculated as a rate or proportion, is:",options:{A:"Mortality",B:"Lethality",C:"Prevalence",D:"Incidence"},correct:"D",explanation:"Incidence measures the frequency of new cases of disease in a population over a specified time period. It reflects disease risk and is used to study the aetiology of disease."},
      {id:"mi-stat-003",topic:"Statistics",subtopic:"Mortality",difficulty:"Easy",question:"The number of deaths in a certain group of people in a certain period of time is:",options:{A:"Incidence",B:"Prevalence",C:"Lethality",D:"Mortality"},correct:"D",explanation:"Mortality is the death rate — the number of deaths in a defined population over a defined time period. It is expressed as deaths per 1,000 or 100,000 population per year."},
      {id:"mi-stat-004",topic:"Statistics",subtopic:"Lethality",difficulty:"Medium",question:"The proportion of deaths among individuals with a particular disease is called:",options:{A:"Mortality",B:"Incidence",C:"Prevalence",D:"Lethality"},correct:"D",explanation:"Lethality (case fatality rate) = deaths from a disease / total cases of that disease. It measures the severity/deadliness of a disease. Mortality measures deaths in the whole population; lethality measures deaths among diagnosed patients."},
      {id:"mi-stat-005",topic:"Statistics",subtopic:"Lethality vs mortality",difficulty:"Hard",question:"The proportion of cases in a designated population of a particular disease that die in a specified period of time is:",options:{A:"Prevalence",B:"Incidence",C:"Mortality rate",D:"Lethality"},correct:"D",explanation:"Lethality (case fatality) = proportion of cases who die. This differs from mortality rate (deaths in the total population). Lethality is disease-specific and measures how deadly the disease is for those who have it."},
      {id:"mi-stat-006",topic:"Statistics",subtopic:"Descriptive statistics",difficulty:"Medium",question:"A branch of statistics that is solely concerned with properties of the observed data and which does not rest on the assumption that data come from a larger population is:",options:{A:"Inferential statistics",B:"Discrete statistics",C:"Descriptive statistics",D:"Nominal statistics"},correct:"C",explanation:"Descriptive statistics summarizes and describes the observed dataset (mean, median, mode, range, graphs) without making inferences about a larger population."},
      {id:"mi-stat-007",topic:"Statistics",subtopic:"Inferential statistics",difficulty:"Medium",question:"Inferential statistics is:",options:{A:"Statistics used to describe and summarize the population data",B:"Statistics solely concerned with data from normal distribution",C:"Statistics solely concerned with properties of observed data without population assumptions",D:"Statistics that generalizes properties of a population from a sample, by testing hypotheses and deriving estimates"},correct:"D",explanation:"Inferential statistics uses sample data to make inferences (generalizations) about the larger population, involving hypothesis testing, confidence intervals, and probability."},
      {id:"mi-stat-008",topic:"Statistics",subtopic:"Mean median mode",difficulty:"Medium",question:"Which measure of central tendency is the middle value when a dataset is ordered from smallest to largest?",options:{A:"Mean",B:"Median",C:"Mode",D:"Range"},correct:"B",explanation:"The median is the middle value of an ordered dataset. For an odd number of values, it is the central value. For an even number, it is the average of the two middle values. It is resistant to outliers."},
      {id:"mi-stat-009",topic:"Statistics",subtopic:"Histogram vs scatterplot",difficulty:"Medium",question:"Which plot is best suited for visualizing the distribution of a single continuous variable (sample distribution)?",options:{A:"Scatterplot",B:"Pie chart",C:"Histogram",D:"Boxplot for two groups"},correct:"C",explanation:"A histogram shows the frequency distribution of a single continuous variable by grouping values into bins. A scatterplot shows the relationship between two continuous variables."},
      {id:"mi-stat-010",topic:"Statistics",subtopic:"Scatterplot",difficulty:"Medium",question:"Which plot is best suited for displaying the possible dependency (correlation) between two continuous variables?",options:{A:"Histogram",B:"Boxplot",C:"Scatterplot",D:"Pie chart"},correct:"C",explanation:"A scatterplot (scatter diagram) plots two continuous variables against each other on x and y axes, revealing correlations or dependencies. A histogram shows single variable distribution."},
      {id:"mi-stat-011",topic:"Statistics",subtopic:"Sensitivity",difficulty:"Hard",question:"What does sensitivity of a diagnostic test mean?",options:{A:"It is the proportion of all negatives correctly identified as negatives",B:"It is the proportion of all positives correctly identified as positives (true positive rate)",C:"It is the proportion of all positives incorrectly identified as negatives",D:"It is the proportion of all negatives incorrectly identified as positives"},correct:"B",explanation:"Sensitivity = True Positives / (True Positives + False Negatives). A sensitive test rarely misses diseased patients (few false negatives). A specific test rarely misclassifies healthy patients (few false positives)."},
      {id:"mi-stat-012",topic:"Statistics",subtopic:"Specificity",difficulty:"Hard",question:"What does specificity of a diagnostic test mean?",options:{A:"It is the proportion of all positives correctly identified as positives",B:"It is the proportion of all negatives incorrectly identified as positives",C:"It is the proportion of all negatives correctly identified as negatives (true negative rate)",D:"It is the proportion of all positives incorrectly identified as negatives"},correct:"C",explanation:"Specificity = True Negatives / (True Negatives + False Positives). A highly specific test rarely labels healthy people as sick. High specificity = few false positives."},
      {id:"mi-stat-013",topic:"Statistics",subtopic:"P-value",difficulty:"Hard",question:"What is a p-value in statistical testing?",options:{A:"The probability that the null hypothesis is true",B:"The probability of results being more extreme than those observed if the null hypothesis were true and the experiment repeated over and over",C:"The minimum significance level required to reject a hypothesis",D:"The proportion of variance explained by the model"},correct:"B",explanation:"The p-value is the probability of obtaining results as extreme or more extreme than observed, assuming the null hypothesis is true. A p-value < 0.05 (1 in 20 probability) is conventionally considered statistically significant."},
      {id:"mi-stat-014",topic:"Statistics",subtopic:"Graphical representation",difficulty:"Easy",question:"Which graphical representation is most appropriate for quantitative continuous data?",options:{A:"Pie chart",B:"Bar chart of categories",C:"Dot plots and histograms",D:"Frequency table only"},correct:"C",explanation:"Quantitative continuous data is best visualized with histograms (distribution) or dot plots. Pie charts and bar charts are more appropriate for categorical data."},
      {id:"mi-stat-015",topic:"Statistics",subtopic:"NNT",difficulty:"Hard",question:"What is the NNT (Number Needed to Treat)?",options:{A:"The number of patients who need to be diagnosed before treatment begins",B:"The number of patients who need to be treated over a specific time period to prevent one additional harmful outcome",C:"The number of trials needed to confirm a treatment effect",D:"The minimum sample size required for a clinical trial"},correct:"B",explanation:"NNT = 1 / Absolute Risk Reduction. It indicates how many patients must be treated to prevent one additional adverse outcome. A lower NNT indicates a more effective treatment."},
    ]},

    { name: 'Evidence-Based Medicine', questions: [
      {id:"mi-ebm-001",topic:"EBM",subtopic:"Definition",difficulty:"Easy",question:"What is EBM (Evidence-Based Medicine)?",options:{A:"A quantitative method of combining the results of independent studies",B:"A probability that results would be more extreme than observed if null hypothesis were true",C:"A judicious and explicit use of current best evidence in making decisions about health care and treatment of individual patients",D:"A study design in which scientific questions are collected and analysed retrospectively"},correct:"C",explanation:"EBM (Evidence-Based Medicine) is the judicious and explicit use of the best current evidence — integrated with clinical expertise and patient values — in making decisions about individual patient care. (Sackett et al.)"},
      {id:"mi-ebm-002",topic:"EBM",subtopic:"EBM pyramid top",difficulty:"Medium",question:"What is on top of the Evidence-Based Medicine pyramid?",options:{A:"Cohort studies",B:"Expert opinion",C:"Case controlled studies",D:"Systematic Reviews / Meta-analyses"},correct:"D",explanation:"The EBM pyramid from lowest to highest evidence: Expert Opinion → Case Reports → Case-Controlled Studies → Cohort Studies → Randomised Controlled Trials (RCTs) → Systematic Reviews / Meta-analyses (top)."},
      {id:"mi-ebm-003",topic:"EBM",subtopic:"Meta-analysis",difficulty:"Medium",question:"What is a meta-analysis?",options:{A:"A study design in which scientific questions are analysed retrospectively",B:"A study where patients are randomly allocated to receive or not receive an exposure",C:"A quantitative method of combining the results of independent studies and synthesizing summaries and conclusions from them",D:"A review of clinical literature focused on one specific intervention topic"},correct:"C",explanation:"Meta-analysis is a statistical technique that combines results from multiple independent studies to produce a single, more precise estimate of an effect. It provides the highest level of quantitative evidence."},
      {id:"mi-ebm-004",topic:"EBM",subtopic:"Systematic review",difficulty:"Medium",question:"What is a systematic review?",options:{A:"A study where individual patients are randomly allocated to receive a treatment",B:"A review of clinical literature focused on one specific intervention or topic, providing more information for most specific situations",C:"A quantitative synthesis of multiple studies using statistical methods",D:"A study following a group of people over time to determine disease outcomes"},correct:"B",explanation:"A systematic review is a rigorous, structured review of the clinical literature focused on a specific clinical question, using explicit methods to identify, critically appraise, and synthesise relevant studies."},
      {id:"mi-ebm-005",topic:"EBM",subtopic:"RCT",difficulty:"Medium",question:"In a Randomised Controlled Trial (RCT), individuals are:",options:{A:"Observed prospectively without any intervention",B:"Randomly allocated to receive or not receive the exposure or preventive procedure being investigated",C:"Selected based on having the disease and compared to those without it",D:"Interviewed retrospectively about past exposures"},correct:"B",explanation:"In an RCT, participants are randomly allocated to an intervention group or control group. Randomisation minimises confounding bias, making RCTs the gold standard for evaluating treatment efficacy."},
      {id:"mi-ebm-006",topic:"EBM",subtopic:"Cohort study",difficulty:"Medium",question:"A cohort study:",options:{A:"Looks at ill patients with varying degrees of illness to evaluate a diagnostic test",B:"Composes people who have the disease with one or more who do not",C:"Follows up people at least one point in time — prospectively observing outcomes in an exposed vs unexposed group",D:"Randomly allocates patients to intervention or control group"},correct:"C",explanation:"A cohort study follows groups of people (cohorts) over time — those exposed to a risk factor vs those not — and compares outcomes. Cohort studies can be prospective or retrospective."},
      {id:"mi-ebm-007",topic:"EBM",subtopic:"Case-control study",difficulty:"Medium",question:"A case-control study:",options:{A:"Randomly allocates individuals to receive a treatment",B:"Follows groups of people prospectively over time",C:"Composes people who have the disease (cases) with those who do not (controls) and compares past exposures",D:"Reviews all available literature on a topic systematically"},correct:"C",explanation:"A case-control study looks backwards — it selects people with the disease (cases) and without (controls), then compares their past exposures to identify risk factors. It is efficient for rare diseases."},
      {id:"mi-ebm-008",topic:"EBM",subtopic:"Blind trial",difficulty:"Hard",question:"In a diagnostic accuracy study, the gold standard test is:",options:{A:"Any test that is currently the cheapest available",B:"A test applied only to healthy participants",C:"The test administered only to the experimental group",D:"The most accurate available reference test — administered to all patients to confirm the true diagnosis"},correct:"D",explanation:"The gold standard is the reference standard — the most accurate available test — administered to all patients in the study so their true disease status can be confirmed, regardless of the test under evaluation."},
      {id:"mi-ebm-009",topic:"EBM",subtopic:"Absolute risk reduction",difficulty:"Hard",question:"What is the Absolute Risk Reduction (ARR)?",options:{A:"The ratio of event rates in the experimental and control groups",B:"The reduction in rates of harmful outcomes between experimental and control groups",C:"The number of patients who need to be treated to prevent one outcome",D:"The probability that a treated patient has a better outcome than an untreated patient"},correct:"B",explanation:"ARR = Event rate in control group − Event rate in experimental group. It represents the absolute decrease in risk attributable to the treatment. NNT = 1/ARR."},
      {id:"mi-ebm-010",topic:"EBM",subtopic:"Correlation vs causation",difficulty:"Medium",question:"A study shows that smoking is correlated with lung cancer. Which statement is most accurate?",options:{A:"Correlation always implies causation in medical research",B:"Because smoking and lung cancer are correlated, smoking directly causes lung cancer without further evidence needed",C:"Correlation indicates an association but does not by itself prove causation — further evidence (dose-response, plausibility, temporality) is required",D:"Correlation is only meaningful when the p-value is less than 0.01"},correct:"C",explanation:"Correlation (association) does not equal causation. Bradford Hill criteria are used to assess causation: strength, consistency, specificity, temporality, biological gradient, plausibility, etc."},
    ]},

    { name: 'Cybersecurity & Internet', questions: [
      {id:"mi-sec-001",topic:"Cybersecurity",subtopic:"Phishing",difficulty:"Easy",question:"What is phishing?",options:{A:"Malware made to damage the target computer or network",B:"Fraudulent website or e-mail trying to obtain sensitive information",C:"Malware made to gather and steal data from a local drive unnoticed",D:"Malware made to block access to data unless a ransom is paid"},correct:"B",explanation:"Phishing is a cyberattack using fraudulent emails or fake websites impersonating trusted entities to trick users into revealing sensitive information (passwords, credit card numbers, etc.)."},
      {id:"mi-sec-002",topic:"Cybersecurity",subtopic:"Ransomware",difficulty:"Easy",question:"What is ransomware?",options:{A:"Malware that gathers and steals data without the user noticing",B:"Malware that makes copies of itself to spread across computers",C:"Malware made to block access to data until a ransom is paid",D:"A fraudulent website trying to obtain sensitive information"},correct:"C",explanation:"Ransomware is malicious software that encrypts a victim's data and demands a ransom payment for the decryption key. Notable examples include WannaCry and Petya."},
      {id:"mi-sec-003",topic:"Cybersecurity",subtopic:"Spyware",difficulty:"Easy",question:"What is spyware?",options:{A:"Malware that blocks access to data until payment",B:"A fraudulent email trying to obtain passwords",C:"Malware that gathers and steals data from a local drive without the user's knowledge",D:"A cyberattack that floods servers with requests"},correct:"C",explanation:"Spyware is malware that secretly collects information about the user (keystrokes, browsing habits, passwords) and transmits it to a third party, all without the user's knowledge or consent."},
      {id:"mi-sec-004",topic:"Cybersecurity",subtopic:"DDoS",difficulty:"Medium",question:"What is a DDoS (Distributed Denial of Service) attack?",options:{A:"Malware that encrypts files and demands ransom",B:"A cyberattack where the server is denied access to users by flooding the machine with requests, overloading the system",C:"A fraudulent website that steals user credentials",D:"Software that monitors network traffic for threats"},correct:"B",explanation:"A DDoS attack floods a target server with so many requests that it becomes overloaded and unavailable to legitimate users — denying service. It is 'distributed' because it uses multiple infected computers (botnets)."},
      {id:"mi-sec-005",topic:"Cybersecurity",subtopic:"Virus",difficulty:"Easy",question:"What is a computer virus?",options:{A:"Malware that blocks access to data until ransom is paid",B:"Malware that makes copies of itself to spread across computers and infect files",C:"Software that monitors network traffic",D:"A fraudulent email requesting personal information"},correct:"B",explanation:"A computer virus is malware that replicates by inserting copies of itself into other programs or files. It spreads when infected files are executed and can corrupt data or damage systems."},
      {id:"mi-sec-006",topic:"Cybersecurity",subtopic:"Malware types",difficulty:"Medium",question:"Which malware type is designed to collect personal data by monitoring user keystrokes and browsing activity without the user knowing?",options:{A:"Ransomware",B:"Spyware",C:"Firewall",D:"Worm"},correct:"B",explanation:"Spyware covertly monitors user activity — keystrokes, web browsing, screenshots — and transmits the collected data to attackers without the user's knowledge. Keyloggers are a common type of spyware."},
      {id:"mi-sec-007",topic:"Cybersecurity",subtopic:"Firewall function",difficulty:"Easy",question:"What is the primary function of a firewall?",options:{A:"To scan files for viruses and remove them",B:"To encrypt data transmitted over the network",C:"To monitor and filter network traffic, blocking unwanted communication",D:"To back up data automatically to a remote server"},correct:"C",explanation:"A firewall filters incoming and outgoing network traffic based on security rules, blocking unauthorized or potentially dangerous connections. It is the first line of network defense."},
      {id:"mi-sec-008",topic:"Cybersecurity",subtopic:"Phishing vs ransomware",difficulty:"Medium",question:"A hospital employee receives an email appearing to be from the IT department asking them to click a link and enter their login credentials. This is most likely:",options:{A:"A DDoS attack",B:"Spyware installation",C:"A phishing attack",D:"A ransomware attack"},correct:"C",explanation:"Asking users to enter credentials via a fake link is classic phishing — impersonating a trusted entity to steal login information. Ransomware would encrypt files; DDoS would flood servers with requests."},
      {id:"mi-sec-009",topic:"Internet",subtopic:"Internet basics",difficulty:"Easy",question:"What is the World Wide Web (WWW)?",options:{A:"The physical infrastructure of cables and routers connecting computers",B:"A system of interlinked hypertext documents and resources accessed via the internet",C:"A private network used only by hospitals",D:"The email communication protocol"},correct:"B",explanation:"The World Wide Web is a system of interlinked hypertext documents (web pages) that are accessed via the internet using web browsers. It was invented by Tim Berners-Lee in 1989 and uses HTTP/HTTPS protocols."},
      {id:"mi-sec-010",topic:"Internet",subtopic:"Cybersecurity best practices",difficulty:"Medium",question:"Which practice best protects against phishing attacks?",options:{A:"Using a faster internet connection",B:"Verifying the sender's email address and never clicking suspicious links",C:"Installing more RAM on the computer",D:"Increasing the screen resolution"},correct:"B",explanation:"Protecting against phishing requires vigilance: verify sender identity, avoid clicking unknown links, check that URLs match legitimate domains, and use multi-factor authentication."},
    ]},

    { name: 'Credit Test Simulation', questions: [
      {id:"mi-ct-001",topic:"Digital Images",subtopic:"Resolution",difficulty:"Easy",question:"How much is the resolution of a digital image which has 1000 pixels in rows and 1000 pixels in columns?",options:{A:"1 Megabyte",B:"1 Megapixel",C:"1 Megabit",D:"1 Byte"},correct:"B",explanation:"Resolution = 1000 × 1000 = 1,000,000 pixels = 1 Megapixel. Resolution is measured in pixels."},
      {id:"mi-ct-002",topic:"Networks",subtopic:"Computer network",difficulty:"Easy",question:"What is true about a computer network?",options:{A:"Computer network means computing power of several computers is summed up and they work as one",B:"Every computer network consists of one control unit and peripheries which are absolutely dependent on it",C:"Computer network is an interconnected system of autonomous computers which can exchange information",D:"Computer network means that several users work on one computer at the same time"},correct:"C",explanation:"A computer network is an interconnected system of autonomous computers that can exchange information."},
      {id:"mi-ct-003",topic:"Statistics",subtopic:"Incidence",difficulty:"Easy",question:"Occurrence of new cases of disease over a specified time period, typically calculated as a rate or proportion, is:",options:{A:"Mortality",B:"Lethality",C:"Prevalence",D:"Incidence"},correct:"D",explanation:"Incidence measures new cases of disease arising in a population during a defined time period."},
      {id:"mi-ct-004",topic:"Cybersecurity",subtopic:"Phishing",difficulty:"Easy",question:"What is phishing?",options:{A:"Malware made to damage the target (computer, network etc.)",B:"Fraudulent website or e-mail trying to obtain sensitive information",C:"Malware made to gather and steal data from local drive unnoticed",D:"Malware made to block access to data unless a ransom is paid"},correct:"B",explanation:"Phishing uses fraudulent websites or emails impersonating trusted entities to trick users into revealing sensitive information."},
      {id:"mi-ct-005",topic:"Statistics",subtopic:"Histogram Y-axis",difficulty:"Medium",question:"Which quantity is on the vertical (Y) axis of an image histogram?",options:{A:"Frequency of pixels / number of pixels",B:"Brightness",C:"Resolution",D:"Contrast"},correct:"A",explanation:"The Y-axis of an image histogram shows the frequency (count) of pixels. The X-axis shows brightness values."},
      {id:"mi-ct-006",topic:"Digital Images",subtopic:"Smallest element",difficulty:"Easy",question:"The smallest element in a 2D image is called:",options:{A:"Boxel",B:"Excel",C:"Matrix",D:"Pixel"},correct:"D",explanation:"A pixel (picture element) is the smallest unit of a 2D digital image."},
      {id:"mi-ct-007",topic:"Statistics",subtopic:"Mortality",difficulty:"Easy",question:"The number of deaths in a certain group of people in a certain period of time is:",options:{A:"Incidence",B:"Prevalence",C:"Mortality",D:"Lethality"},correct:"C",explanation:"Mortality = the death rate; the number of deaths in a defined population over a defined time period."},
      {id:"mi-ct-008",topic:"Networks",subtopic:"Peer-to-peer",difficulty:"Medium",question:"How do we call architecture of a network where computers are equally privileged, equipotent participants in the application?",options:{A:"Terminator architecture",B:"Client-Server architecture",C:"IPVP architecture",D:"Peer-to-peer architecture"},correct:"D",explanation:"In peer-to-peer (P2P) architecture, all computers are equally privileged and can act as both client and server."},
      {id:"mi-ct-009",topic:"MS Excel",subtopic:"Division formula",difficulty:"Easy",question:"Choose the correct expression which will divide cells A1 and A2 in MS Excel:",options:{A:"$A1/$A2",B:"=A1%A2",C:"=A1/A2",D:"A1/A2"},correct:"C",explanation:"=A1/A2 correctly divides the value in A1 by A2. Formulas must start with = and use / for division."},
      {id:"mi-ct-010",topic:"Hardware",subtopic:"Bit",difficulty:"Easy",question:"What is true about a bit?",options:{A:"10^2 different values can be saved in one bit",B:"50 different values can be saved in one bit",C:"Only 2 different values can be saved in one bit (e.g. yes/no)",D:"10 different values can be saved in one bit"},correct:"C",explanation:"A bit can hold exactly 2 values: 0 or 1 (binary digit)."},
      {id:"mi-ct-011",topic:"Statistics",subtopic:"Inferential statistics",difficulty:"Medium",question:"Inferential statistics is:",options:{A:"Statistics that is used to describe and summarize the population data",B:"Statistics which is solely concerned with data that comes from normal distribution",C:"Statistics which is solely concerned with properties of the observed data and does not rest on the assumption that data come from a larger population",D:"Statistics that generalizes properties of a population from properties of a sample, for example by testing hypotheses and deriving estimates"},correct:"D",explanation:"Inferential statistics generalizes from sample data to the larger population using hypothesis testing and estimation."},
      {id:"mi-ct-012",topic:"Statistics",subtopic:"Median",difficulty:"Medium",question:"Calculate the median of: 8, 5, 2, 3, 1, 8, 2, 5, 1",options:{A:"1",B:"2",C:"3",D:"5"},correct:"C",explanation:"Sorted: 1,1,2,2,3,5,5,8,8. Median = 5th value = 3."},
      {id:"mi-ct-013",topic:"Databases",subtopic:"Boolean AND",difficulty:"Medium",question:"What does AND mean when you create the query in databases?",options:{A:"It reduces the number of results",B:"It does not take the last keyword into account",C:"It increases the number of results",D:"It does not take the first keyword into account"},correct:"A",explanation:"AND requires all specified terms to be present — this narrows and reduces the number of results."},
      {id:"mi-ct-014",topic:"Networks",subtopic:"LAN",difficulty:"Easy",question:"Which type of network is home Wifi with one access point?",options:{A:"MAN",B:"WAN",C:"LAN",D:"PAN"},correct:"C",explanation:"Home WiFi with one access point is a LAN (Local Area Network) covering a small geographic area."},
      {id:"mi-ct-015",topic:"EBM",subtopic:"EBM pyramid",difficulty:"Medium",question:"What is on top of the evidence-based medicine pyramid?",options:{A:"Cohort studies",B:"Expert opinion",C:"Case controlled studies",D:"Systematic Reviews"},correct:"D",explanation:"Systematic Reviews (and meta-analyses) sit at the top of the EBM pyramid, providing the highest level of evidence."},
    ]},

  ];
})();
